class BloomFilter {
  private size: number;
  private bits: boolean[];

  constructor(size = 100) {
    this.size = size;
    this.bits = new Array(size).fill(false);
  }

  private hash1(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash * 31 + str.charCodeAt(i)) % this.size;
    }
    return hash;
  }

  private hash2(str: string): number {
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) + hash + str.charCodeAt(i)) % this.size;
    }
    return Math.abs(hash);
  }

  add(item: string) {
    this.bits[this.hash1(item)] = true;
    this.bits[this.hash2(item)] = true;
  }

  contains(item: string): boolean {
    return this.bits[this.hash1(item)] && this.bits[this.hash2(item)];
  }
}

async function getUser(id: string): Promise<User> {
  // 1. Check cache
  const cached = await redis.get(`user:${id}`);
  if (cached) return JSON.parse(cached);

  // 2. Cache miss - fetch from DB
  const user = await db.users.findUnique({ where: { id } });
  if (!user) throw new NotFoundError();

  // 3. Populate cache with TTL
  await redis.setex(`user:${id}`, 3600, JSON.stringify(user));
  return user;
}

// Invalidate on write
async function updateUser(id: string, data: Partial<User>) {
  await db.users.update({ where: { id }, data });
  await redis.del(`user:${id}`);  // bust cache
}

func GetUser(ctx context.Context, id string) (*User, error) {
    // Check cache
    cached, err := rdb.Get(ctx, "user:"+id).Result()
    if err == nil {
        var u User
        json.Unmarshal([]byte(cached), &u)
        return &u, nil
    }

    // Cache miss
    u, err := db.QueryUser(ctx, id)
    if err != nil {
        return nil, err
    }

    // Populate cache (1 hour TTL)
    data, _ := json.Marshal(u)
    rdb.Set(ctx, "user:"+id, data, time.Hour)
    return u, nil
}

import redis
import json
from functools import wraps

r = redis.Redis()

def cached(ttl=3600):
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            key = f"{fn.__name__}:{args}:{kwargs}"
            hit = r.get(key)
            if hit:
                return json.loads(hit)
            result = fn(*args, **kwargs)
            r.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator

